using System.Security.Claims;
using System.Text.Json;
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Sem.Authentication;
using Sem.Web.Data;
using Sem.Web.Runtime;
int checks=0;void Check(bool ok,string label){if(!ok)throw new Exception(label);checks++;}
var file=Path.Combine(Path.GetTempPath(),"sem-invitation-admin-"+Guid.NewGuid().ToString("N")+".db");
try{
 var services=new ServiceCollection();services.AddLogging();services.AddDbContext<ApplicationDbContext>(o=>o.UseSqlite("Data Source="+file));services.AddIdentityCore<ApplicationUser>(o=>o.Stores.SchemaVersion=IdentitySchemaVersions.Version3).AddEntityFrameworkStores<ApplicationDbContext>();await using var provider=services.BuildServiceProvider();await using var scope=provider.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();var users=scope.ServiceProvider.GetRequiredService<UserManager<ApplicationUser>>();await SqliteStorageInitializer.InitializeAsync(db);
 var actor=new ApplicationUser{Id="actor",UserName="actor@example.invalid",Email="actor@example.invalid",EmailConfirmed=true,Enabled=true,DisplayName="合成管理者",SecurityStamp="stamp"};db.Users.Add(actor);db.Users.Add(new(){Id="other",DisplayName="<img src=x> 他人",UserName="other@example.invalid",Email="PRIVATE_EMAIL"});await db.SaveChangesAsync();Check((await users.AddOrUpdatePasskeyAsync(actor,new([1],[11,22],DateTimeOffset.UtcNow,777,["internal"],true,true,true,[44],[55]))).Succeeded,"合成パスキー");
 var identity=new IdentityOptions();ClaimsPrincipal Who(string stamp="stamp",bool duplicate=false,string? session="session")=>new(new ClaimsIdentity(new[]{new Claim(identity.ClaimsIdentity.UserIdClaimType,"actor"),new Claim(identity.ClaimsIdentity.SecurityStampClaimType,stamp),new Claim(ClaimTypes.Role,"ServiceAdmin")}.Concat(session==null?[]:[new Claim(AuthenticationSession.SessionClaim,session)]).Concat(duplicate?[new Claim(identity.ClaimsIdentity.UserIdClaimType,"actor")]:[]),"synthetic"));
 Task<InvitationAdministrationResult> Read(int page=0,ClaimsPrincipal? who=null)=>InvitationAdministrationReader.ReadAsync(db,who??Who(),identity,page);
 Check((await Read()).State=="forbidden","ServiceAdmin claimでも現DB非管理者は拒否");actor.IsAdmin=true;await db.SaveChangesAsync();
 for(int n=0;n<102;n++)db.InvitationRequests.Add(new(){Id=$"request-{n:000}",UserId="other",Reason="<script>合成理由</script>",Count=3,Days=7,Created=n+1,Status=n==101?"Rejected":"Pending",DecidedBy="missing",DecisionComment=n==101?"合成判断":null});
 db.Invitations.AddRange(new Invitation{Id="direct",OwnerId="actor",IssuerId="actor",IssuanceSource="Direct",Purpose="合成の発行目的",Created=100,Limit=3,Expires=DateTimeOffset.UtcNow.AddDays(1).ToUnixTimeSeconds(),TokenHash="PRIVATE_TOKEN_HASH",ProtectedToken="PRIVATE_PROTECTED"},new Invitation{Id="request",TokenHash="PRIVATE_REQUEST",OwnerId="actor",IssuerId="missing",RequestId="request-001",Limit=1,Uses=1,Created=99,Expires=DateTimeOffset.UtcNow.AddDays(1).ToUnixTimeSeconds()},new Invitation{Id="revoked",TokenHash="PRIVATE_REVOKED",OwnerId="missing",IssuerId="missing",Disabled=true,RevokedBy="other",RevocationReason="<script>漏えい対処</script>",RevokedAt=1,Created=98},new Invitation{Id="legacy",TokenHash="PRIVATE_LEGACY",OwnerId="other",IssuerId="missing",RequestId="missing-request"},new Invitation{Id="orphan",TokenHash="PRIVATE_ORPHAN",OwnerId="actor",IssuerId="missing",RequestId="missing-request-2",IssuanceSource="Request"});await db.SaveChangesAsync();
 var before=File.ReadAllBytes(file);var wal=File.Exists(file+"-wal")?File.ReadAllBytes(file+"-wal"):[];var result=await Read();var v=result.View!;
 Check(result.State=="ok"&&v.ActorId=="actor"&&v.Requests.Length==100&&v.MoreRequests,"現DB全体管理者は他人依頼も各100件");Check(v.Requests[0].RequesterName=="<img src=x> 他人"&&v.Requests[0].Record.DeciderName==null,"表示名のみ・不明判断者を推測しない");Check(v.Links.Single(x=>x.Record.Id=="direct").Source=="Direct","明示発行方式");Check(v.Links.Single(x=>x.Record.Id=="request").Source=="Request"&&v.Links.Single(x=>x.Record.Id=="request").IssuerName==null,"実依頼関連と欠損発行者");Check(v.Links.Single(x=>x.Record.Id=="request").RequesterName=="<img src=x> 他人","リクエスト元は所有者の推測でなく実依頼の本人");Check(v.Links.Single(x=>x.Record.Id=="legacy").Source=="Unknown","存在しない依頼の旧方式を推測しない");Check(v.Links.Single(x=>x.Record.Id=="orphan").Source=="Request"&&v.Links.Single(x=>x.Record.Id=="orphan").RequesterName==null,"明示の発行方式は保持し欠損依頼元は不明");Check(v.Links.Single(x=>x.Record.Id=="revoked").RevokerName=="<img src=x> 他人"&&v.Links.Single(x=>x.Record.Id=="revoked").RevokedAt!=null,"実失効記録の最小参照");
 foreach(var secret in new[]{"PRIVATE_EMAIL","PRIVATE_TOKEN_HASH","PRIVATE_PROTECTED","TokenHash","ProtectedToken","SecurityStamp","@example.invalid"})Check(!JsonSerializer.Serialize(v).Contains(secret),"秘密値なし "+secret);
 Check(before.SequenceEqual(File.ReadAllBytes(file))&&wal.SequenceEqual(File.Exists(file+"-wal")?File.ReadAllBytes(file+"-wal"):[])&&!db.ChangeTracker.HasChanges(),"参照でDB・WAL・監査変更なし");var second=(await Read(1)).View!;Check(second.Requests.Length==2&&!second.MoreRequests&&second.Links.Length==0,"次の100件と正しい末尾");Check((await Read(-1)).State=="invalid-request"&&(await Read(int.MaxValue)).State=="invalid-request","不正ページ拒否");
 Check((await Read(who:new(new ClaimsIdentity()))).State=="unauthorized","匿名拒否");Check((await Read(who:Who("old"))).State=="unauthorized","古いstamp拒否");Check((await Read(who:Who(duplicate:true))).State=="unauthorized","多重claim拒否");Check((await Read(who:Who(session:null))).State=="unauthorized","sessionなし拒否");actor.IsAdmin=false;await db.SaveChangesAsync();Check((await Read()).State=="forbidden","現在権限の剥奪を即反映");actor.IsAdmin=true;actor.Enabled=false;await db.SaveChangesAsync();Check((await Read()).State=="unauthorized","無効本人拒否");actor.Enabled=true;actor.EmailConfirmed=false;await db.SaveChangesAsync();Check((await Read()).State=="unauthorized","メール未確認拒否");actor.EmailConfirmed=true;await db.SaveChangesAsync();db.RevokedAuthSessions.Add(new(){UserId=actor.Id,TokenHash=AuthenticationSession.Hash("session"),RevokedAt=DateTimeOffset.UtcNow.ToString("O")});await db.SaveChangesAsync();Check((await Read()).State=="unauthorized","失効sessionで全体記録なし");Console.WriteLine($"招待管理者の現在権限・最小参照・不変 {checks}検査: 成功（合成DBのみ）");
}finally{Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();foreach(var p in new[]{file,file+"-wal",file+"-shm"})File.Delete(p);}
